#ifndef MATERIAL_SHARED_PENDING_ATLAS_H
#define MATERIAL_SHARED_PENDING_ATLAS_H
namespace pending_atlas {
struct Metric {uint64_t slot,source,target,chart,method;S vertex[3][2],normal[2];Q lower,upper,scale;};
struct Witness {uint64_t slot,source,target,chart,stage;S free,lower,upper;Q Rlo,Rhi,width_lower,width_upper;};
struct Work {uint64_t slot=0,source=0,target=0,oblique_panels=0;std::array<target::ClippedChart,6>chart;bool seen[6]={},oblique[6]={};std::vector<TypedPanel>panel;std::vector<Metric>metric;Witness witness={};bool complete=false;int failed_chart=-1;std::string reason;};
static void add(Work&w,target::ClipPanel panel,uint64_t cap){need(w.panel.size()+w.oblique_panels<cap/256,"combined regular/retained-oblique slot panel budget");TypedPanel z={};z.slot=w.slot;z.source=w.source;z.index=w.panel.size();z.target=w.target;z.geometry=panel;z.dependent=panel.whole?-1:panel.strip.dependent;z.policy=panel.whole?0:z.dependent==1?1:2;z.lower=panel.strip.lower;z.upper=panel.strip.upper;w.panel.push_back(z);}
// A fixed supporting-line distance for the actual convex reference triangle.
// Choose only its three edge normals, with either sign. Every vertex satisfies
// n.X>=separation; therefore the entire triangle has r>=separation/|n|.
// This is a geometry bound, not an angle/accuracy fallback search.
static Metric distance(const curved::Packet&p,const sd::Compiled&m,const sd::Chart&chart,const Work&w,int ci){Metric z={};z.slot=w.slot;z.source=w.source;z.target=w.target;z.chart=ci;for(int a=0;a<3;a++)for(int b=0;b<3;b++)for(int k=0;k<2;k++)z.vertex[a][k]=z.vertex[a][k]+chart.vertex[a][b]*m.base.vertex[b][k];
 for(int a=0;a<3;a++){int b=(a+1)%3;Q N[2]={-(z.vertex[b][1].n-z.vertex[a][1].n),z.vertex[b][0].n-z.vertex[a][0].n};S length2=S(N[0])*S(N[0])+S(N[1])*S(N[1]);if(!(sf::lower(length2)>0))continue;Q length=sf::upper(mf::root(length2)),lo=__builtin_huge_valq(),hi=-__builtin_huge_valq();for(int j=0;j<3;j++){S dot=S(N[0])*z.vertex[j][0]+S(N[1])*z.vertex[j][1];lo=std::min(lo,sf::lower(dot));hi=std::max(hi,sf::upper(dot));}Q separation=std::max(lo,-hi),r=separation>0?mf::FP<Q>::down(separation/length):Q(0);if(r>z.lower){z.lower=r;z.upper=length;int sign=lo>=-hi?1:-1;for(int k=0;k<2;k++)z.normal[k]=S(sign)*S(N[k]);}}
 need(z.lower>0,"actual nonorigin chart has a strict supporting-line distance");z.scale=mf::FP<Q>::down(std::min(z.lower,Q(p.parameters[3]))/Q(8));need(z.scale>0,"positive original density/gravity chart scale");return z;}
static void regular(const curved::Packet&p,const sd::Compiled&m,const std::vector<target::Face>&faces,Work&w,int ci,uint64_t cap){const auto&c=w.chart[ci];const auto&reference=c.reference;auto metric=distance(p,m,reference,w,ci);w.metric.push_back(metric);auto f=target::frame(m,reference,sf::range(0,1));Q scale=metric.scale;
 if(c.coordinate.whole){int nr=std::max(1,int(ceilq(std::max(sf::mag(f.D[0]),sf::mag(f.D[1]))/scale))),nt=std::max(4,int(ceilq(std::max(sf::mag(f.E[0]),sf::mag(f.E[1]))/scale)));for(int i=0;i<nr;i++)for(int j=0;j<nt;j++){target::ClipPanel b;b.reference=reference;b.whole=true;b.strip.chart=ci;b.ordinary={ci,i,j,nr,nt,S(i)/S(nr),S(i+1)/S(nr),S(j)/S(nt),S(j+1)/S(nt)};add(w,b,cap);}return;}
 auto shape=target::shape_bounds(m);
 for(const auto&strip:c.strip){auto local=target::frame(m,reference,strip.dependent?sf::range(0,1):sf::range(sf::lower(strip.lo),sf::upper(strip.hi)));Q D=std::max(sf::mag(local.D[0]),sf::mag(local.D[1])),E=std::max(sf::mag(local.E[0]),sf::mag(local.E[1])),base=strip.dependent?D:E,free_bound=base,dependent_bound=strip.dependent?E:D;
  for(int index:{strip.lower,strip.upper})if(index>=0){auto cone=target::gradient_cone(faces[index],shape);S numerator,denominator;for(int k=0;k<2;k++){numerator=numerator+cone.gradient[k]*(strip.dependent?local.D[k]:local.E[k]);denominator=denominator+cone.gradient[k]*(strip.dependent?local.E[k]:local.D[k]);}Q minimum=sf::lower(denominator)>0?sf::lower(denominator):-sf::upper(denominator);need(minimum>0,"retained selected branch derivative separates");free_bound=std::max(free_bound,sf::add(base,sf::mul(dependent_bound,sf::quotient(sf::mag(numerator),minimum))));}
  need(free_bound>0&&dependent_bound>0,"positive selected-branch metric");Q max_step=mf::FP<Q>::down(scale/free_bound);int neta=std::max(16,int(ceilq(dependent_bound/scale)));need(neta>0&&uint64_t(neta)<=cap/256,"finite deterministic regular eta plan");S left=strip.lo;bool pole=strip.dependent==1&&(strip.lower>=0||strip.upper>=0);
  while(left.n<strip.hi.n){Q step=max_step;if(pole){need(sf::lower(left)>0,"genuine regular angular graph excludes apex");step=std::min(step,mf::FP<Q>::down(sf::lower(left)/Q(3)));}Q next=mf::FP<Q>::down(left.n+step);bool last=next>=sf::lower(strip.hi);S right=last?strip.hi:S(next);need(sf::lower(right)>sf::upper(left),"separated regular full-event endpoints");for(int j=0;j<neta;j++){target::ClipPanel b;b.reference=reference;b.strip=strip;b.strip.lo=left;b.strip.hi=right;b.eta_lo=S(j)/S(neta);b.eta_hi=S(j+1)/S(neta);add(w,b,cap);}if(last)break;left=right;}
 }
}
static void origin(const curved::Packet&p,const sd::Compiled&m,const std::vector<target::Face>&faces,Work&w,int ci,uint64_t cap){const auto&c=w.chart[ci];const auto&reference=c.reference;auto f=target::frame(m,reference,sf::range(0,1));Q D=std::max(sf::mag(f.D[0]),sf::mag(f.D[1])),E=std::max(sf::mag(f.E[0]),sf::mag(f.E[1]));need(D>0&&E>0,"positive origin directions");Q Rlo=__builtin_huge_valq(),Rhi=0;
 for(int j=0;j<16;j++){auto ray=target::frame(m,reference,sf::range(Q(j)/16,Q(j+1)/16));S square=ray.D[0]*ray.D[0]+ray.D[1]*ray.D[1];need(sf::lower(square)>0,"original origin ray length excludes zero");S length=mf::root(square);Rlo=std::min(Rlo,sf::lower(length));Rhi=std::max(Rhi,sf::upper(length));}need(Rlo>0&&Rhi>=Rlo,"positive origin ray range");Metric metric={};metric.slot=w.slot;metric.source=w.source;metric.target=w.target;metric.chart=ci;metric.method=1;metric.lower=Rlo;metric.upper=Rhi;metric.scale=Q(p.parameters[7]);w.metric.push_back(metric);
 std::vector<target::Strip>strips=c.strip;if(c.coordinate.whole)strips={{ci,1,-1,-1,S(0),S(1)}};
 for(const auto&strip:strips){if(strip.dependent==0){for(int j=0;j<16;j++){S a=strip.lo+(strip.hi-strip.lo)*S(j)/S(16),b=strip.lo+(strip.hi-strip.lo)*S(j+1)/S(16),free=sf::range(sf::lower(a),sf::upper(b)),lower(0),upper(1);if(strip.lower>=0)lower=target::graph(faces[strip.lower],reference,c.coordinate,strip.lower,free);if(strip.upper>=0)upper=target::graph(faces[strip.upper],reference,c.coordinate,strip.upper,free);Q width_lower=mf::FP<Q>::down(sf::lower(upper)-sf::upper(lower)),width_upper=sf::add(sf::upper(upper),-sf::lower(lower));w.witness.stage=2;w.witness.free=free;w.witness.lower=lower;w.witness.upper=upper;w.witness.Rlo=Rlo;w.witness.Rhi=Rhi;w.witness.width_lower=width_lower;w.witness.width_upper=width_upper;need(width_lower>0&&width_upper>0,"positive actual radial graph-family width");S eta(0);while(eta.n<1){Q sl=std::max(Q(0),mf::FP<Q>::down(sf::lower(lower)+sf::lower(eta)*width_lower)),density=mf::FP<Q>::down(sl*Rlo+Q(p.parameters[7])),step=std::min(Q(.25L),mf::FP<Q>::down(density/(Q(8)*Rhi*width_upper)));need(step>0,"positive original radial density grading");Q next=mf::FP<Q>::down(eta.n+step);bool last=next>=1;S right=last?S(1):S(next);need(sf::lower(right-eta)>0,"separated graded radial eta");target::ClipPanel panel;panel.reference=reference;panel.strip=strip;panel.strip.lo=a;panel.strip.hi=b;panel.eta_lo=eta;panel.eta_hi=right;add(w,panel,cap);if(last)break;eta=right;}}continue;}
  need(strip.dependent==1,"saved origin dependent axis");S left=strip.lo;while(left.n<strip.hi.n){Q s_lower=std::max(Q(0),sf::lower(left)),density=mf::FP<Q>::down(s_lower*Rlo+Q(p.parameters[7])),step=std::min(mf::FP<Q>::down(density/(Q(8)*Rhi)),mf::FP<Q>::down(Q(p.parameters[3])/(Q(8)*D)));bool implicit=strip.lower>=0||strip.upper>=0;if(implicit){need(sf::lower(left)>0,"genuine origin angular graph starts beyond apex event");step=std::min(step,mf::FP<Q>::down(sf::lower(left)/Q(3)));}need(step>0,"positive original density pole step");Q next=mf::FP<Q>::down(left.n+step);bool last=next>=sf::lower(strip.hi);S right=last?strip.hi:S(next);need(sf::lower(right)>sf::upper(left),"separated full origin event endpoints");Q scale=mf::FP<Q>::down(density/Q(8)),stretch=sf::mul(std::max(Q(0),sf::upper(right)),E);int neta=std::max(16,int(ceilq(stretch/scale)));need(neta>0&&uint64_t(neta)<=cap/256,"finite original-order origin angular metric");for(int j=0;j<neta;j++){target::ClipPanel panel;panel.reference=reference;if(!implicit){panel.whole=true;panel.strip.chart=ci;panel.ordinary={ci,0,j,1,neta,left,right,S(j)/S(neta),S(j+1)/S(neta)};}else{panel.strip=strip;panel.strip.lo=left;panel.strip.hi=right;panel.eta_lo=S(j)/S(neta);panel.eta_hi=S(j+1)/S(neta);}add(w,panel,cap);}if(last)break;left=right;}
 }
}
static void plan(const curved::Packet&p,const sd::Compiled&m,const std::vector<target::Face>&faces,Work&w,uint64_t cap){for(int ci=0;ci<6;ci++){w.failed_chart=ci;w.witness.slot=w.slot;w.witness.source=w.source;w.witness.target=w.target;w.witness.chart=ci;w.witness.stage=1;need(w.seen[ci],"explicit stored reference packet for each chart");if(w.oblique[ci])continue;const auto&c=w.chart[ci];need(c.complete,"completed restored geometry");if(c.coordinate.empty)continue;bool at_origin=true;for(int k=0;k<2;k++)at_origin=at_origin&&m.base.vertex[c.reference.apex][k].n==0&&m.base.vertex[c.reference.apex][k].e==0;if(at_origin)origin(p,m,faces,w,ci,cap);else regular(p,m,faces,w,ci,cap);}w.failed_chart=-1;w.complete=true;w.reason="same_actual174_chart_fixed_typed_plan_complete_no_clearance_or_all12";}
}
#endif
